using TechTalk.SpecFlow;\nusing RestSharp;\nusing Serilog;\n\nnamespace AutomationFramework.API.StepDefinitions {\n    [Binding]\n    public class PetstoreCRUDStepDefinitions {\n        private readonly ScenarioContext scenarioContext;\n        private RestClient client;\n        private RestRequest request;\n        private RestResponse response;\n\n        public PetstoreCRUDStepDefinitions(ScenarioContext scenarioContext) {\n            this.scenarioContext = scenarioContext;\n            client = new RestClient(\"https://petstore.swagger.io/v2\");\n        }\n\n        [Given(@\"I have a pet payload\")]\n        public void GivenIHaveAPetPayload() {\n            var petPayload = new {\n                id = 12345,\n                name = \"Doggie\",\n                status = \"available\"\n            };\n            scenarioContext[\"PetPayload\"] = petPayload;\n        }\n\n        [When(@\"I send a POST request to the petstore API\")]\n        public void WhenISendAPOSTRequestToThePetstoreAPI() {\n            request = new RestRequest(\"/pet\", Method.POST);\n            request.AddJsonBody(scenarioContext[\"PetPayload\"]);\n            response = client.Execute(request);\n            scenarioContext[\"Response\"] = response;\n            Log.Information(\"POST request sent to /pet with payload: {@PetPayload}\", scenarioContext[\"PetPayload\"]);\n        }\n\n        [Then(@\"I should receive a 200 OK response\")]\n        public void ThenIShouldReceiveA200OKResponse() {\n            response = (RestResponse)scenarioContext[\"Response\"];\n            if (response.StatusCode != System.Net.HttpStatusCode.OK) {\n                Log.Error(\"Expected 200 OK but received {StatusCode}\", response.StatusCode);\n                throw new Exception($\"Expected 200 OK but received {response.StatusCode}\");\n            }\n            Log.Information(\"Received 200 OK response\");\n        }\n\n        [Then(@\"the pet should be created\")]\n        public void ThenThePetShouldBeCreated() {\n            var createdPet = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(response.Content);\n            if (createdPet.id != 12345) {\n                Log.Error(\"Pet ID mismatch. Expected 12345 but received {PetId}\", createdPet.id);\n                throw new Exception($\"Pet ID mismatch. Expected 12345 but received {createdPet.id}\");\n            }\n            Log.Information(\"Pet created with ID: {PetId}\", createdPet.id);\n        }\n\n        [Given(@\"I have the ID of an existing pet\")]\n        public void GivenIHaveTheIDOfAnExistingPet() {\n            scenarioContext[\"PetId\"] = 12345;\n        }\n\n        [When(@\"I send a GET request to the petstore API\")]\n        public void WhenISendAGETRequestToThePetstoreAPI() {\n            var petId = scenarioContext[\"PetId\"];\n            request = new RestRequest($\"/pet/{petId}\", Method.GET);\n            response = client.Execute(request);\n            scenarioContext[\"Response\"] = response;\n            Log.Information(\"GET request sent to /pet/{PetId}\", pet